import { inject, Injectable } from "@angular/core";
import { SuperService } from "./super.service";
import { Solicitud, Archivo } from "../models/solicitud.model";
import { ApiServiceService } from "../services/api/api-service.service";
import { Observable } from "rxjs";

@Injectable({
    providedIn: 'root'
})
export class SolicitudService extends SuperService<Solicitud> {
    protected model = 'solicitudes';
    protected columns: (keyof Solicitud)[] = [
        'id',
        'nombre_solicitante',
        'puesto_solicitante',
        'email_solicitante',
        'nombre_empresa',
        'municipio_id',
        'num_empleados',
        'ano_inicio_operaciones',
        'giro_principal_id',
        'otro_giro',
        'es_miembro_asociacion',
        'asociacion_id',
        'otra_asociacion',
        'relacionado_gobierno',
        'otro_nivel_gobierno',
        'relacionado_sitio_web',
        'otra_limitante_sitio_web',
        'relacionado_leyes',
        'relacionado_tramites',
        'relacionado_mercado',
        'otra_limitante_mercado',
        'descripcion_limitante',
        'propuesta_solucion',
        'created_at',
        'updated_at',
        'deleted_at',
        'municipio',
        'giro_principal',
        'asociacion',
        'niveles_gobierno',
        'limitantes_sitio_web',
        'problemas_regulacion',
        'problemas_tramite',
        'limitantes_mercado',
        'archivos'
    ];

    private apiService = inject(ApiServiceService);

    downloadArchivo(solicitudId: number, archivoId: number): Observable<Blob> {
        const endpoint = `api/solicitudes/${solicitudId}/archivos/${archivoId}`;
        return this.apiService.downloadFile(endpoint);
    }
}
